ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS tire_rotation_km integer NOT NULL DEFAULT 15000;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS tire_last_rotation_km integer;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS tire_last_pressure_date date;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS tire_psi_front smallint NOT NULL DEFAULT 33;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS tire_psi_rear smallint NOT NULL DEFAULT 33;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS tire_psi_loaded_front smallint NOT NULL DEFAULT 36;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS tire_psi_loaded_rear smallint NOT NULL DEFAULT 41;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS tire_psi_spare smallint NOT NULL DEFAULT 35;
CREATE TABLE IF NOT EXISTS "tires" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "deleted_at" TIMESTAMP WITH TIME ZONE, "created_by" uuid, "updated_by" uuid, "version" integer NOT NULL DEFAULT '1', "vehicle_id" uuid NOT NULL, "number" smallint NOT NULL, "position" character varying(3), "brand" character varying(60) NOT NULL, "model" character varying(60) NOT NULL, "size" character varying(30) NOT NULL, "price_cents" integer, "installed_odometer" integer NOT NULL, "installed_date" date NOT NULL, "store" character varying(120), "life_km" integer NOT NULL, "front_km" integer NOT NULL DEFAULT '0', "rear_km" integer NOT NULL DEFAULT '0', "base_odometer" integer NOT NULL, "pressure_psi" numeric(4,1), "manufacture_year" smallint, "tread_file_id" uuid, "side_file_id" uuid, CONSTRAINT "pk_tires" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "uq_tires_vehicle_id_position" ON "tires" ("vehicle_id", "position") WHERE "position" IS NOT NULL AND "deleted_at" IS NULL;
CREATE TABLE IF NOT EXISTS "tire_events" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "deleted_at" TIMESTAMP WITH TIME ZONE, "created_by" uuid, "updated_by" uuid, "version" integer NOT NULL DEFAULT '1', "vehicle_id" uuid NOT NULL, "tire_id" uuid NOT NULL, "kind" character varying(12) NOT NULL, "date" date NOT NULL, "odometer" integer NOT NULL, "description" character varying(200) NOT NULL, "pressure_psi" numeric(4,1), "damage_type" character varying(30), "severity" character varying(10), "repaired" boolean NOT NULL DEFAULT false, "cost_cents" integer, "notes" character varying(200), "file_id" uuid, CONSTRAINT "pk_tire_events" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_tire_events_tire_id_date" ON "tire_events" ("tire_id", "date");
CREATE TABLE IF NOT EXISTS "tire_rotations" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "created_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updated_at" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "deleted_at" TIMESTAMP WITH TIME ZONE, "created_by" uuid, "updated_by" uuid, "version" integer NOT NULL DEFAULT '1', "vehicle_id" uuid NOT NULL, "date" date NOT NULL, "odometer" integer NOT NULL, "kind" character varying(10) NOT NULL, CONSTRAINT "pk_tire_rotations" PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_tire_rotations_vehicle_id_date" ON "tire_rotations" ("vehicle_id", "date");
ALTER TABLE "tires" ADD CONSTRAINT "fk_tires_vehicle_id" FOREIGN KEY ("vehicle_id") REFERENCES "vehicles"("id") ON DELETE CASCADE ON UPDATE NO ACTION;
ALTER TABLE "tire_events" ADD CONSTRAINT "fk_tire_events_tire_id" FOREIGN KEY ("tire_id") REFERENCES "tires"("id") ON DELETE CASCADE ON UPDATE NO ACTION;
ALTER TABLE "tire_rotations" ADD CONSTRAINT "fk_tire_rotations_vehicle_id" FOREIGN KEY ("vehicle_id") REFERENCES "vehicles"("id") ON DELETE CASCADE ON UPDATE NO ACTION;
